import React, { useState, useEffect } from "react";
import KeyMetrics from "./dashboard/KeyMetrics";
import HospitalOverview from "./dashboard/HospitalOverview";
import SystemStatus from "./dashboard/SystemStatus";
import QuickActions from "./dashboard/QuickActions";
import DepartmentOPD from "./dashboard/DepartmentOPD";
import TopDoctors from "./dashboard/TopDoctors";
import RevenueOverview from "./dashboard/RevenueOverview";
import RecentActivity from "./dashboard/RecentActivity";
import DailyRevenue from "./dashboard/DailyRevenue";
import DoctorRevenue from "./dashboard/DoctorRevenue";
import API_BASE_URL from "../config/api";
import "./Dashboard.css";

function Dashboard({ onNavigate, refreshKey }) {
  const [metrics, setMetrics] = useState(null);
  const [overview, setOverview] = useState(null);
  const [systemStatus, setSystemStatus] = useState(null);
  const [departmentOPD, setDepartmentOPD] = useState(null);
  const [topDoctors, setTopDoctors] = useState(null);
  const [revenue, setRevenue] = useState(null);
  const [recentActivity, setRecentActivity] = useState(null);
  const [dailyRevenue, setDailyRevenue] = useState(null);
  const [doctorRevenue, setDoctorRevenue] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, [refreshKey]);

  useEffect(() => {
    const interval = setInterval(() => {
      fetchDashboardData();
    }, 30000); // Refresh every 30 seconds

    return () => clearInterval(interval);
  }, []);

  const fetchDashboardData = async () => {
    try {
      // Fetch each endpoint individually to handle partial failures
      const endpoints = [
        { name: 'metrics', url: `${API_BASE_URL}/dashboard/metrics` },
        { name: 'overview', url: `${API_BASE_URL}/dashboard/overview` },
        { name: 'status', url: `${API_BASE_URL}/dashboard/system-status` },
        { name: 'opd', url: `${API_BASE_URL}/dashboard/department-opd` },
        { name: 'doctors', url: `${API_BASE_URL}/dashboard/top-doctors` },
        { name: 'revenue', url: `${API_BASE_URL}/dashboard/revenue` },
        { name: 'activity', url: `${API_BASE_URL}/dashboard/recent-activity` },
        { name: 'dailyRevenue', url: `${API_BASE_URL}/dashboard/daily-revenue` },
        { name: 'doctorRevenue', url: `${API_BASE_URL}/dashboard/doctor-revenue` },
      ];

      const results = await Promise.allSettled(
        endpoints.map(async (endpoint) => {
          try {
            const response = await fetch(endpoint.url);
            if (!response.ok) {
              console.warn(`${endpoint.name} returned ${response.status}`);
              return { name: endpoint.name, data: null, error: true };
            }
            const data = await response.json();
            return { name: endpoint.name, data, error: false };
          } catch (err) {
            console.error(`Error fetching ${endpoint.name}:`, err);
            return { name: endpoint.name, data: null, error: true };
          }
        })
      );

      results.forEach((result) => {
        if (result.status === 'fulfilled' && !result.value.error) {
          const { name, data } = result.value;
          switch (name) {
            case 'metrics': setMetrics(data); break;
            case 'overview': setOverview(data); break;
            case 'status': setSystemStatus(data); break;
            case 'opd': setDepartmentOPD(data); break;
            case 'doctors': setTopDoctors(data); break;
            case 'revenue': setRevenue(data); break;
            case 'activity': setRecentActivity(data); break;
            case 'dailyRevenue': setDailyRevenue(data); break;
            case 'doctorRevenue': setDoctorRevenue(data); break;
          }
        }
      });

      setLoading(false);
    } catch (error) {
      console.error("Error fetching dashboard data:", error);
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="dashboard-loading">Loading dashboard...</div>;
  }

  return (
    <div className="dashboard">
      <div className="dashboard-main">
        <div className="dashboard-header">
          <div className="dashboard-header-left">
            <div className="dashboard-logo-box">
              <img
                src="/logo.png"
                alt="Divine Hospital"
                className="dashboard-logo"
              />
            </div>
            <div className="dashboard-brand-text">
              <span className="dashboard-hospital-name">DIVINE HOSPITAL</span>
              <h2>Welcome back, Admin</h2>
              <p className="dashboard-subtitle">
                Here is your hospital overview for today with key metrics and
                operations.
              </p>
            </div>
          </div>

          <div className="dashboard-header-right">
            <div className="user-menu">
              <div className="user-avatar">AD</div>
              <div className="user-menu-text">
                <strong>Admin</strong>
                <span>Control Panel</span>
              </div>
            </div>
          </div>
        </div>

        <KeyMetrics metrics={metrics} />

        <div className="dashboard-grid">
          <div className="dashboard-card full">
            <QuickActions onNavigate={onNavigate} />
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card large">
            <HospitalOverview data={overview} />
          </div>
          <div className="dashboard-card medium">
            <SystemStatus services={systemStatus} />
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card medium">
            <DepartmentOPD data={departmentOPD} />
          </div>
          <div className="dashboard-card medium">
            <TopDoctors data={topDoctors} />
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card medium">
            <RevenueOverview data={revenue} />
          </div>
          <div className="dashboard-card medium">
            <RecentActivity data={recentActivity} />
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card full">
            <DailyRevenue />
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card full">
            <DoctorRevenue />
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
