import React, { useState, useEffect } from "react";
import API_BASE_URL from "../config/api";
import "./BillDetails.css";

function BillDetails() {
  const [bills, setBills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");

  useEffect(() => {
    fetchBills();
  }, []);

  const fetchBills = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/billing`);
      const data = await response.json();
      setBills(Array.isArray(data) ? data : []);
      setLoading(false);
    } catch (err) {
      console.error("Failed to fetch bills:", err);
      setBills([]);
      setLoading(false);
    }
  };

  const handlePrint = (billId) => {
    window.print();
  };

  const filteredBills = bills.filter((bill) => {
    const matchesSearch =
      bill.patient_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      bill.patient_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      bill.bill_number?.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesStatus =
      filterStatus === "all" || bill.status === filterStatus;

    return matchesSearch && matchesStatus;
  });

  if (loading) return <div className="loading">Loading bills...</div>;

  return (
    <div className="bill-details">
      <div className="bill-details-header">
        <h2>Bill Details</h2>
        <p>View and manage patient billing information</p>
      </div>

      <div className="bill-filters">
        <input
          type="search"
          placeholder="Search by patient, ID, or bill number..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="search-input"
        />
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="filter-select"
        >
          <option value="all">All Status</option>
          <option value="paid">Paid</option>
          <option value="pending">Pending</option>
          <option value="partial">Partial</option>
        </select>
      </div>

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>Bill Number</th>
              <th>Patient</th>
              <th>Patient ID</th>
              <th>Bill Date</th>
              <th>Bill Type</th>
              <th>Total Amount</th>
              <th>Paid Amount</th>
              <th>Balance</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredBills.length > 0 ? (
              filteredBills.map((bill) => (
                <tr key={bill.id}>
                  <td>{bill.bill_number}</td>
                  <td>{bill.patient_name}</td>
                  <td>{bill.patient_id}</td>
                  <td>{new Date(bill.bill_date).toLocaleDateString()}</td>
                  <td>{bill.bill_type}</td>
                  <td>₹{bill.total_amount?.toLocaleString()}</td>
                  <td>₹{bill.paid_amount?.toLocaleString()}</td>
                  <td>₹{(bill.total_amount - bill.paid_amount)?.toLocaleString()}</td>
                  <td>
                    <span className={`status ${bill.status}`}>
                      {bill.status}
                    </span>
                  </td>
                  <td>
                    <button
                      className="btn btn-sm btn-print"
                      onClick={() => handlePrint(bill.id)}
                    >
                      Print
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="10" className="no-data">
                  No bills found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default BillDetails;
