import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import API_BASE_URL from "../config/api";
import "./Auth.css";

const API_BASES = [API_BASE_URL].filter(Boolean);

function Auth() {
  const { login, user } = useAuth();
  const navigate = useNavigate();
  const [mode, setMode] = useState("login");
  const [formData, setFormData] = useState({
    password: "",
    confirmPassword: "",
    email: "",
    first_name: "",
    last_name: "",
    token: "",
  });
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    const saved = localStorage.getItem("accessToken");
    if (saved) {
      navigate("/");
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    try {
      const endpointPath =
        mode === "signup"
          ? "/signup"
          : mode === "login"
            ? "/login"
            : mode === "forgot"
              ? "/forgot-password"
              : "/reset-password";

      const payload =
        mode === "signup"
          ? {
              email: formData.email,
              password: formData.password,
              confirmPassword: formData.confirmPassword,
              first_name: formData.first_name,
              last_name: formData.last_name,
            }
          : mode === "login"
            ? { email: formData.email, password: formData.password }
            : mode === "forgot"
              ? { email: formData.email }
              : { token: formData.token, password: formData.password };

      let lastError = null;
      for (const base of API_BASES) {
        try {
          const response = await fetch(`${base}${endpointPath}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });

          const data = await response.json();
          if (!response.ok)
            throw new Error(
              data.error || `Request failed (${response.status})`,
            );

          if (mode === "login" || mode === "signup") {
            login(data.user, data.accessToken, data.refreshToken);
            // Redirect based on user role
            if (data.user?.role === 'doctor') {
              navigate("/doctors");
            } else {
              navigate("/");
            }
            return;
          }

          if (mode === "forgot") {
            setMessage(data.message || "Reset instructions sent");
            setMode("reset");
            return;
          }

          setMessage(data.message || "Password reset successful");
          setMode("login");
          return;
        } catch (err) {
          lastError = err;
        }
      }

      throw lastError || new Error("Unable to reach authentication server");
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="auth-shell">
      <div className="auth-card">
        <div className="auth-branding">
          <div className="auth-logo-wrap">
            <img
              src="/logo.png"
              alt="Divine Hospital logo"
              className="auth-logo-image"
            />
          </div>
          <div className="auth-brand-copy">
            <span className="auth-kicker">DIVINE HOSPITAL</span>
            <h2>
              {mode === "signup"
                ? "Create Account"
                : mode === "login"
                  ? "Hospital Login"
                  : mode === "forgot"
                    ? "Forgot Password"
                    : "Reset Password"}
            </h2>
            <p>
              {mode === "signup"
                ? "Create a new account to access the hospital dashboard"
                : mode === "login"
                  ? "Access your dashboard securely"
                  : mode === "forgot"
                    ? "Enter your email to receive reset instructions"
                    : "Use the reset token sent to your email"}
            </p>
          </div>
        </div>

        {error ? <div className="auth-error">{error}</div> : null}
        {message ? <div className="auth-success">{message}</div> : null}

        <form className="auth-form" onSubmit={handleSubmit}>
          {mode === "login" ? (
            <>
              <input
                name="email"
                type="email"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
                required
              />
              <input
                name="password"
                type="password"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
                required
              />
            </>
          ) : null}

          {mode === "signup" ? (
            <>
              <div className="auth-grid">
                <input
                  name="first_name"
                  placeholder="First Name"
                  value={formData.first_name}
                  onChange={handleChange}
                  required
                />
                <input
                  name="last_name"
                  placeholder="Last Name"
                  value={formData.last_name}
                  onChange={handleChange}
                  required
                />
              </div>
              <input
                name="email"
                type="email"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
                required
              />
              <input
                name="password"
                type="password"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
                required
              />
              <input
                name="confirmPassword"
                type="password"
                placeholder="Confirm Password"
                value={formData.confirmPassword}
                onChange={handleChange}
                required
              />
            </>
          ) : null}

          {mode === "forgot" ? (
            <input
              name="email"
              type="email"
              placeholder="Email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          ) : null}

          {mode === "reset" ? (
            <>
              <input
                name="token"
                placeholder="Reset Token"
                value={formData.token}
                onChange={handleChange}
                required
              />
              <input
                name="password"
                type="password"
                placeholder="New Password"
                value={formData.password}
                onChange={handleChange}
                required
              />
            </>
          ) : null}

          <button type="submit">
            {mode === "signup"
              ? "Create Account"
              : mode === "login"
                ? "Login"
                : mode === "forgot"
                  ? "Send Reset Link"
                  : "Reset Password"}
          </button>
        </form>

        <div className="auth-actions">
          {mode === "login" && (
            <>
              <div className="auth-link" onClick={() => setMode("signup")}>
                Create an account
              </div>
              <div className="auth-link" onClick={() => setMode("forgot")}>
                Forgot Password?
              </div>
            </>
          )}

          {mode === "signup" && (
            <div className="auth-link" onClick={() => setMode("login")}>
              Already have an account? Login
            </div>
          )}

          {mode === "forgot" && (
            <div className="auth-link" onClick={() => setMode("login")}>
              Back to login
            </div>
          )}

          {mode === "reset" && (
            <div className="auth-link" onClick={() => setMode("login")}>
              Back to login
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Auth;
