import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { doctorService } from "../services/doctorService";
import { useAuth } from "../contexts/AuthContext";

const DoctorPanel = ({ searchQuery }) => {
  const navigate = useNavigate();
  const { user, updateUser } = useAuth();
  const [doctorData, setDoctorData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchDoctorData();
  }, []);

  const fetchDoctorData = async () => {
    try {
      setLoading(true);
      // Fetch doctor data based on logged-in user
      const doctors = await doctorService.getAllDoctors();
      const currentDoctor = doctors.find(doc => doc.user_id === user?.id);
      
      if (!currentDoctor) {
        setError("Doctor profile not found for your account");
        setDoctorData(null);
        return;
      }
      
      setDoctorData(currentDoctor);
      
      // Update user context with doctor's name if not already set
      if (user && (!user.first_name || user.first_name === 'System')) {
        updateUser({
          ...user,
          first_name: currentDoctor.first_name,
          last_name: currentDoctor.last_name
        });
      }
    } catch (err) {
      setError("Failed to fetch doctor data");
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="doctor-panel-container">
      <div className="doctor-panel-header">
        <h2>Doctor Panel</h2>
        <p>Welcome, Dr. {doctorData?.first_name} {doctorData?.last_name}</p>
      </div>

      <div className="doctor-panel-content">
        <div className="doctor-info-card">
          <h3>Doctor Information</h3>
          <div className="info-grid">
            <div className="info-item">
              <label>Name:</label>
              <span>{doctorData?.first_name} {doctorData?.last_name}</span>
            </div>
            <div className="info-item">
              <label>Email:</label>
              <span>{doctorData?.email}</span>
            </div>
            <div className="info-item">
              <label>Phone:</label>
              <span>{doctorData?.phone}</span>
            </div>
            <div className="info-item">
              <label>Department:</label>
              <span>{doctorData?.department_name}</span>
            </div>
            <div className="info-item">
              <label>Specialization:</label>
              <span>{doctorData?.specialization}</span>
            </div>
            <div className="info-item">
              <label>Qualification:</label>
              <span>{doctorData?.qualification}</span>
            </div>
            <div className="info-item">
              <label>Experience:</label>
              <span>{doctorData?.experience_years} years</span>
            </div>
            <div className="info-item">
              <label>Consultation Fee:</label>
              <span>₹{doctorData?.consultation_fee}</span>
            </div>
            <div className="info-item">
              <label>Status:</label>
              <span className={`status ${doctorData?.is_available ? "active" : "inactive"}`}>
                {doctorData?.is_available ? "Available" : "Unavailable"}
              </span>
            </div>
          </div>
        </div>

        <div className="doctor-quick-actions">
          <h3>Quick Actions</h3>
          <div className="actions-grid">
            <button className="action-card" onClick={() => navigate('/schedule')}>
              <span className="action-icon">📅</span>
              <span>View Schedule</span>
            </button>
            <button className="action-card" onClick={() => navigate('/leave')}>
              <span className="action-icon">🏖️</span>
              <span>Request Leave</span>
            </button>
            <button className="action-card" onClick={() => navigate('/admin/commission')}>
              <span className="action-icon">💰</span>
              <span>View Commission</span>
            </button>
            <button className="action-card" onClick={() => navigate('/opd/list')}>
              <span className="action-icon">👥</span>
              <span>My Patients</span>
            </button>
          </div>
        </div>

        <div className="doctor-login-info">
          <h3>Login Information</h3>
          <div className="info-grid">
            <div className="info-item">
              <label>Username:</label>
              <span>{user?.username || 'Not set'}</span>
            </div>
            <div className="info-item">
              <label>Default Password:</label>
              <span className="password-highlight">doctor123</span>
            </div>
            <div className="info-item">
              <label>Email:</label>
              <span>{user?.email || doctorData?.email}</span>
            </div>
          </div>
          <p className="password-note">Please change your password after first login for security.</p>
        </div>
      </div>
    </div>
  );
};

export default DoctorPanel;
