import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config/api";
import "./ReceptionistDashboard.css";

const ReceptionistDashboard = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    todayOPD: 0,
    todayIPD: 0,
    activePatients: 0,
    availableAppointments: 0
  });
  const [recentPatients, setRecentPatients] = useState([]);
  const [doctorAvailability, setDoctorAvailability] = useState([]);
  const [showIPDTimings, setShowIPDTimings] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const token = localStorage.getItem('token');
        const headers = {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        };

        const [statsRes, patientsRes, doctorsRes] = await Promise.all([
          fetch(`${API_BASE_URL}/receptionist/dashboard-stats`, { headers }),
          fetch(`${API_BASE_URL}/receptionist/recent-patients`, { headers }),
          fetch(`${API_BASE_URL}/receptionist/doctor-availability`, { headers })
        ]);

        const statsData = await statsRes.json();
        const patientsData = await patientsRes.json();
        const doctorsData = await doctorsRes.json();

        setStats(statsData);
        setRecentPatients(patientsData);
        setDoctorAvailability(doctorsData);
      } catch (err) {
        setError("Failed to load dashboard data");
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  if (loading) {
    return <div className="loading">Loading dashboard...</div>;
  }

  return (
    <div className="dashboard-container">
      <div className="page-header">
        <h2>🏥 Receptionist Dashboard</h2>
      </div>

      {error && <div className="error-message">{error}</div>}

      {/* Statistics Cards */}
      <div className="stats-grid">
        <div className="stat-card stat-card-opd" onClick={() => navigate('/opd/list')}>
          <div className="stat-icon">🏥</div>
          <div className="stat-info">
            <h3>{stats.todayOPD}</h3>
            <p>Today's OPD</p>
          </div>
        </div>

        <div className="stat-card stat-card-ipd" onClick={() => navigate('/ipd/list')}>
          <div className="stat-icon">🛏️</div>
          <div className="stat-info">
            <h3>{stats.todayIPD}</h3>
            <p>Today's IPD</p>
          </div>
        </div>

        <div className="stat-card stat-card-appointments" onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          console.log('Clicked on Available Slots');
          setShowIPDTimings(true);
        }}>
          <div className="stat-icon">📅</div>
          <div className="stat-info">
            <h3>{stats.availableAppointments}</h3>
            <p>Available Slots</p>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="quick-actions">
        <h3>⚡ Quick Actions</h3>
        <div className="action-buttons">
          <button className="action-btn" onClick={() => navigate('/opd/registration')}>
            New OPD Registration
          </button>
          <button className="action-btn" onClick={() => navigate('/ipd/registration')}>
            New IPD Admission
          </button>
          <button className="action-btn" onClick={() => navigate('/ipd/generate-invoice')}>
            Create Invoice
          </button>
          <button className="action-btn" onClick={() => navigate('/admin/doctors')}>
            View Doctors
          </button>
        </div>
      </div>

      {/* Recent Patients */}
      <div className="recent-section">
        <h3>Recent Patients</h3>
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Patient ID</th>
                <th>Name</th>
                <th>Phone</th>
                <th>Type</th>
                <th>Doctor</th>
                <th>Date</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {recentPatients.length > 0 ? (
                recentPatients.slice(0, 10).map((patient) => (
                  <tr key={patient.id}>
                    <td>{patient.patient_id || '-'}</td>
                    <td>
                      {patient.first_name} {patient.last_name}
                    </td>
                    <td>{patient.phone || '-'}</td>
                    <td>{patient.visit_type || '-'}</td>
                    <td>
                      {patient.doctor_first_name || patient.doctor_last_name
                        ? `Dr. ${patient.doctor_first_name || ''} ${patient.doctor_last_name || ''}`.trim()
                        : '-'}
                    </td>
                    <td>
                      {patient.visit_date || patient.admission_date
                        ? new Date(patient.visit_date || patient.admission_date).toLocaleDateString('en-IN')
                        : '-'}
                    </td>
                    <td>
                      <span className={`status ${patient.status || 'active'}`}>
                        {patient.status || 'Active'}
                      </span>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '2rem' }}>
                    No recent patients found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Doctor Availability */}
      <div className="recent-section">
        <h3>Doctor Availability Status</h3>
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Doctor</th>
                <th>Specialization</th>
                <th>Status</th>
                <th>Available Time</th>
              </tr>
            </thead>
            <tbody>
              {doctorAvailability.length > 0 ? (
                doctorAvailability.map((doctor) => (
                  <tr key={doctor.id}>
                    <td>
                      Dr. {doctor.first_name} {doctor.last_name}
                    </td>
                    <td>{doctor.specialization || '-'}</td>
                    <td>
                      <span 
                        className={`status ${doctor.current_status === 'In Hospital' ? 'active' : doctor.current_status === 'On Leave' ? 'inactive' : 'pending'}`}
                      >
                        {doctor.current_status}
                      </span>
                    </td>
                    <td>
                      {doctor.available_start && doctor.available_end
                        ? `${new Date(`2000-01-01T${doctor.available_start}`).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })} - ${new Date(`2000-01-01T${doctor.available_end}`).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}`
                        : '-'}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" style={{ textAlign: 'center', padding: '2rem' }}>
                    No doctors found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* IPD Timings Modal */}
      {showIPDTimings && (
        <div className="modal-overlay" onClick={() => setShowIPDTimings(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>📅 IPD Timings</h3>
              <button className="modal-close" onClick={() => setShowIPDTimings(false)}>
                ✕
              </button>
            </div>
            <div className="modal-body">
              <div className="ipd-timings">
                <div className="timing-item">
                  <span className="timing-label">Morning Shift:</span>
                  <span className="timing-value">9:00 AM - 1:00 PM</span>
                </div>
                <div className="timing-item">
                  <span className="timing-label">Afternoon Shift:</span>
                  <span className="timing-value">2:00 PM - 6:00 PM</span>
                </div>
                <div className="timing-item">
                  <span className="timing-label">Evening Shift:</span>
                  <span className="timing-value">6:00 PM - 10:00 PM</span>
                </div>
                <div className="timing-item">
                  <span className="timing-label">Night Shift:</span>
                  <span className="timing-value">10:00 PM - 9:00 AM</span>
                </div>
                <div className="timing-item">
                  <span className="timing-label">Emergency:</span>
                  <span className="timing-value">24 Hours Available</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReceptionistDashboard;
